// ─── B5 — Digital Contracts + E-Signatures (HelloSign Embedded) ───────────────
//
// Two-layer contract scope:
//   Layer 1 — Platform Liability Waiver (TGP ↔ Client): REQUIRED once per
//             client. Modeled as a ContractTemplate with is_platform=true,
//             owned by the seeded TGP "system coach" user. A client who has
//             a SIGNED platform-waiver envelope at the current template
//             version is grandfathered and never re-signs.
//   Layer 2 — Coach Service Agreement (Coach ↔ Client): OPT-IN per package
//             via CoachPackage.requires_contract + contract_template_id.
//
// Provider-agnostic by construction (spec §11): the models, controllers,
// state machine, checkout integration and audit log do not know which
// SignatureProvider is bound. Only the adapter changes (HelloSign v1;
// DocuSign / native-canvas are future flag-flips, shipped here as stubs).
//
// FEATURE_CONTRACTS_ENABLED is the global go-live gate (default OFF in prod);
// it is enforced as a server-side code-level invariant in
// ContractEnvelopeService.createEnvelope() and the webhook handler.

enum ContractEnvelopeStatus {
  DRAFT
  SENT
  VIEWED
  SIGNED
  DECLINED
  EXPIRED
}

model ContractTemplate {
  id                  String   @id @default(cuid())
  // For coach templates this is the authoring coach. For the platform
  // liability waiver (is_platform=true) this points at the seeded TGP
  // system-coach user so the FK stays NOT NULL and the relation is uniform.
  coach_id            String
  // B5 Layer-1 marker. true = TGP↔Client platform liability waiver (one
  // per client, version-grandfathered). false = coach-authored Layer-2
  // service agreement. Default false keeps coach CRUD behavior unchanged.
  is_platform         Boolean  @default(false)
  name                String
  body_markdown       String
  version             Int      @default(1)
  dynamic_fields_json Json
  requires_signature  Boolean  @default(true)
  created_at          DateTime @default(now())

  coach     User               @relation("ContractTemplateCoach", fields: [coach_id], references: [id])
  envelopes ContractEnvelope[]
  packages  CoachPackage[]     @relation("PackageContractTemplate")

  @@index([coach_id])
  @@index([is_platform, version])
}

model ContractEnvelope {
  id                   String                 @id @default(cuid())
  template_id          String
  // Locked at send time (spec §5.2): a coach editing a template never
  // mutates a contract a client was already sent or signed.
  template_version     Int
  client_id            String
  coach_id             String
  // Nullable — set ONLY after Stripe payment success (spec §3.3 / §4.1).
  purchase_id          String?
  status               ContractEnvelopeStatus @default(DRAFT)
  // Carries the ACTIVE provider's request id regardless of provider
  // (DocuSign envelope id / native-canvas job id when those flags are on).
  // Column name kept per operator spec for migration stability; treated as
  // a generic provider-request-id at the code layer.
  hellosign_request_id String?
  signed_pdf_url       String?
  ip                   String?
  user_agent           String?
  signed_at            DateTime?
  // Default now()+7d at SENT (set in code, not as a column default).
  expires_at           DateTime?
  created_at           DateTime               @default(now())

  template ContractTemplate     @relation(fields: [template_id], references: [id])
  client   User                 @relation("ClientEnvelopes", fields: [client_id], references: [id])
  coach    User                 @relation("CoachEnvelopes", fields: [coach_id], references: [id])
  events   ContractAuditEvent[]
  purchase ClientPurchase?      @relation("PurchaseContractEnvelope")

  @@index([client_id])
  @@index([coach_id])
  @@index([status])
  @@index([hellosign_request_id])
  // Idempotency spine for the Layer-1 grandfather check: find a client's
  // SIGNED platform-waiver envelope by template + version fast.
  @@index([client_id, template_id, template_version, status])
}

model ContractAuditEvent {
  id          String   @id @default(cuid())
  envelope_id String
  // null for system / provider-originated events.
  actor_id    String?
  // VIEW | SIGN | DECLINE | SEND | EXPIRE | WEBHOOK
  action      String
  ip          String?
  user_agent  String?
  created_at  DateTime @default(now())

  envelope ContractEnvelope @relation(fields: [envelope_id], references: [id])

  @@index([envelope_id])
}

// ============================================================
// ROMAN — Phase 1 chat MVP (additive; gated behind
// FEATURE_ROMAN_CHAT_ENABLED, default OFF). See src/roman/.
// ============================================================

// Which app surface a Roman session belongs to. One Roman, two framings:
// `client` (the TGP client app) and `coach` (the coach app). Surface drives
// the system-prompt framing only — the voice contract is identical.
enum RomanSurface {
  client
  coach
}

// Author of a single chat turn. `user` = the human; `roman` = the single AI
// persona. Stored lowercase so raw SQL / admin tooling reads naturally.
enum RomanMessageRole {
  user
  roman
}

// A persistent Roman chat session. Idempotent on (user_id, surface, day_key):
// the service opens at most one active session per user/surface/day. Soft
// delete via deleted_at (never hard-deleted from the chat surface).
model RomanSession {
  id      String       @id @default(cuid())
  user_id String
  surface RomanSurface

  // Idempotency key for "open or resume" — the UTC calendar day (YYYY-MM-DD)
  // the session was opened. The unique index below makes "one active session
  // per (user, surface, day)" a database invariant, not just service logic.
  day_key String

  // Lightweight session bookkeeping. message_count is denormalised for cheap
  // listing; last_activity_at advances on every appended turn.
  message_count    Int      @default(0)
  started_at       DateTime @default(now())
  last_activity_at DateTime @default(now())

  // Voice-contract self-rate-limiting state (spec §1.5 / brief §2). The
  // service surfaces these to the model so it can honour the per-session quip
  // allowance and the single-exclamation budget.
  quips_in_session Int     @default(0)
  exclamation_used Boolean @default(false)

  // Optional brief/subject context blob (e.g. a coach brief) the session was
  // opened against. Nullable — most sessions carry none.
  subject_context_json Json?

  created_at DateTime  @default(now())
  updated_at DateTime  @updatedAt
  // Soft-delete tombstone. Non-null = session is hidden from the chat surface
  // but retained for audit/budget history.
  deleted_at DateTime?

  user     User           @relation("RomanSessionUser", fields: [user_id], references: [id], onDelete: Cascade)
  messages RomanMessage[]

  // Idempotency spine for open-or-resume: at most one row per
  // (user, surface, day_key). The partial-by-convention uniqueness is enforced
  // in full (including soft-deleted rows) so a deleted session does not free
  // the day-key for a duplicate; the service resumes a live one or opens the
  // next day.
  @@unique([user_id, surface, day_key], name: "roman_session_user_surface_day")
  // Listing index: a user's sessions for a surface, newest first.
  @@index([user_id, surface, created_at(sort: Desc)])
}

// A single chat turn within a Roman session. Append-only in practice; an
// assistant turn may be marked `interrupted` when the client disconnects
// mid-stream (partial content persisted).
model RomanMessage {
  id         String           @id @default(cuid())
  session_id String
  // Denormalised owner for direct RLS scoping (avoids a join through session
  // on the hot read path). Always equals the parent session's user_id; the
  // RLS policy enforces both the direct predicate AND the session-join.
  user_id    String
  role       RomanMessageRole
  content    String

  // Token accounting for future budgeting (brief §3). Null on a user turn
  // (no model call) until/unless we attribute prompt tokens to the turn.
  prompt_tokens     Int?
  completion_tokens Int?
  // The Anthropic model id that produced an assistant turn (null on user
  // turns). Persisted so a later model upgrade is auditable per-message.
  model_id          String?

  // True when an assistant turn was persisted from a partial stream because
  // the client disconnected before completion (brief §1.3 streaming rule).
  interrupted Boolean @default(false)

  // Optional branch pointer for future message-tree editing. Nullable; Phase 1
  // never sets it but the column ships now so branching is additive later.
  parent_message_id String?

  created_at DateTime @default(now())

  session RomanSession   @relation(fields: [session_id], references: [id], onDelete: Cascade)
  user    User           @relation("RomanMessageUser", fields: [user_id], references: [id], onDelete: Cascade)
  parent  RomanMessage?  @relation("RomanMessageParent", fields: [parent_message_id], references: [id])
  replies RomanMessage[] @relation("RomanMessageParent")

  // Hot read path: a session's messages in chronological order (the controller
  // paginates newest-first by reversing a created_at cursor over this index).
  @@index([session_id, created_at])
  // Direct owner scope for RLS / per-user budget queries.
  @@index([user_id])
  @@index([parent_message_id])
}

// ── Roman P4 (Option C) — first-payment notification ledger ──────────────────
// DB-enforced "exactly once, forever": the coachId @unique constraint is what
// guarantees a coach's first-ever client payment fires the celebration exactly
// once. Scope is PER COACH, FOREVER — NOT per coach×client: any later payment
// from any client (the same one or a different one) is suppressed once a coach
// has had their first-ever (R81 F3 — the constraint is on coachId alone). A
// DIFFERENT coach still gets their own first-ever celebration even for the same
// client. The Stripe webhook handler performs a direct INSERT inside the same
// $transaction that records the purchase; on the second (retry / second
// payment) attempt the unique constraint raises P2002 and the emit silently
// no-ops (logged structured). No check-then-act / pre-SELECT: the constraint IS
// the race protection (50-Failures #28, #29). Purely additive; no existing
// table or column is modified.
model CoachFirstPaymentNotification {
  id        String   @id @default(cuid())
  coachId   String   @unique // <- DB enforces "exactly once" PER COACH, FOREVER
  coach     User     @relation("CoachFirstPaymentNotificationCoach", fields: [coachId], references: [id])
  amount    Int // cents
  currency  String
  clientId  String
  createdAt DateTime @default(now())

  @@map("coach_first_payment_notification")
}

// ============================================================
// COMMUNITY v3-4 — community search index + wearable-aware
// coaching prompts. Additive only (R69 / R76 §6 — no existing
// community table is altered, no FK on an existing table changes).
//
// All three tables ship behind feature flags (FEATURE_COMMUNITY_SEARCH
// and FEATURE_COMMUNITY_WEARABLE_PROMPTS, both default OFF) and carry
// RLS policies defined in their migrations. Following the v1-1 /
// classroom / voice-note convention, the new tables reference User /
// CommunityWorkspace / CommunityCohort by SCALAR id only (FK enforced
// at the SQL migration layer) — NOT via Prisma `@relation` back-edges —
// so the v3-4 lane never edits the shared User / Workspace models
// (R77 scope discipline). The only Prisma-level relation is the
// self-contained prompt → prompt-source edge below.
// ============================================================

// Search-index kinds. Mirrors the four searchable community object
// families (post, classroom lesson, voice-note TRANSCRIPT-only, event).
// A SQL enum so an unknown kind can never be written.
enum CommunitySearchKind {
  post
  classroom_lesson
  voice_note_transcript
  event

  @@map("CommunitySearchKind")
}

// One denormalized, PII-stripped search row per searchable target. The
// indexer extracts ONLY title / tag / public-metadata text into `excerpt`
// (never message/post/DM bodies, never wearable metric values — see
// V3_4_PREFLIGHT_NOTES §8) and the migration adds a tsvector + GIN index
// over it. `@@unique([workspaceId, kind, targetId])` makes re-indexing
// the same target idempotent (brief test 7).
model CommunitySearchEntry {
  id             String              @id @default(cuid())
  workspaceId    String              @db.Uuid
  cohortId       String?             @db.Uuid
  kind           CommunitySearchKind
  targetId       String              @db.Uuid
  authorId       String?             @db.Uuid
  // First 500 chars of PII-stripped, body-free text — the tsvector basis.
  excerpt        String              @db.Text
  // Role allowlist the row is visible to: subset of ['coach','assistant','student'].
  visibleToRoles String[]
  createdAt      DateTime            @default(now()) @db.Timestamptz(6)
  softDeletedAt  DateTime?           @db.Timestamptz(6)

  @@unique([workspaceId, kind, targetId])
  @@index([workspaceId, cohortId, kind, createdAt])
  // tsvector column + GIN index added via raw SQL in the migration.
  @@map("community_search_entries")
}

// A coach-facing, AI-generated coaching prompt sourced from a client's
// already-opted-in wearable insight (e.g. "Sarah's HRV dropped 12% this
// week"). NEVER readable by the client (RLS coach-only). The 24h cooldown
// per (coachId, clientId, metricKey) is enforced by a partial unique index
// in the migration, not application logic alone (brief §thresholds).
model CommunityWearablePrompt {
  id          String                          @id @default(uuid()) @db.Uuid
  workspaceId String                          @db.Uuid
  coachId     String
  clientId    String
  metricKey   String                          @db.VarChar(64)
  promptText  String                          @db.Text
  sources     CommunityWearablePromptSource[]
  generatedAt DateTime                        @default(now()) @db.Timestamptz(6)
  dismissedAt DateTime?                       @db.Timestamptz(6)
  actedOnAt   DateTime?                       @db.Timestamptz(6)

  @@index([workspaceId, coachId, generatedAt])
  @@index([workspaceId, coachId, dismissedAt])
  @@map("community_wearable_prompts")
}

// Audit trail: which real WearableSample.id drove which prompt. Every
// CommunityWearablePrompt has >= 1 source (brief test 4). `sampleId`
// references WearableSample.id from the existing wearables subsystem —
// scalar only (no cross-subsystem Prisma relation; FK at SQL layer).
model CommunityWearablePromptSource {
  id            String                  @id @default(uuid()) @db.Uuid
  promptId      String                  @db.Uuid
  sampleId      String
  metricKey     String                  @db.VarChar(64)
  observedValue Decimal                 @db.Decimal(18, 6)
  prompt        CommunityWearablePrompt @relation(fields: [promptId], references: [id], onDelete: Cascade)

  @@index([promptId])
  @@index([sampleId])
  @@map("community_wearable_prompt_sources")
}

// ============================================================
// TALENT MARKETPLACE — TM-1 schema + RLS foundation (ADR-0002, refs #424).
// Two-sided public job board. Schema is APPEND-ONLY (R71 shared-file
// discipline): no existing model/User back-relations are edited. Every
// user/listing/application FK is a SCALAR column (TEXT, matching User.id);
// the foreign-key + RLS policies are authored in the SQL migration
// 20261220000000_talent_marketplace_rls, which is the single source of
// truth for referential integrity and tenancy here (same idiom as the
// CommunityWearablePromptSource cross-subsystem scalar above).
//
// NO CoachConnectAccount (ADR decision 3: Connect reuses /coach/connect/*).
// ============================================================

// Public job-listing lifecycle. Only `published` rows are anon-readable.
enum JobListingStatus {
  draft
  published
  closed
}

// How a hirer specifies offered compensation on a listing / offer.
enum CoachCompensationType {
  commission
  rev_share
  flat
  hybrid
}

// Application lifecycle for a listing-scoped Application (PII).
enum ApplicationStatus {
  submitted
  screening
  shortlisted
  offered
  placed
  rejected
  withdrawn
}

// Offer lifecycle (financial). The partial unique indexes in the migration
// enforce one `pending` per (head_coach, application) and one `accepted`
// per application even under a concurrent accept race.
enum CoachOfferStatus {
  pending
  accepted
  rejected
  withdrawn
}

// ─── JobListing ───────────────────────────────────────────────────────────────
//
// A publicly browsable, SEO-indexable job posting authored by a verified
// hirer (head-coach / solo coach / gym owner — verification gating lands in
// TM-2). `hirer_id` is the owning User (scalar FK at SQL layer). Anon may
// SELECT only rows where status = 'published' (RLS public-read).
model JobListing {
  id                 String                @id @default(uuid())
  hirer_id           String
  title              String
  description        String
  specialty          String?
  location           String?
  modality           String?
  compensation_type  CoachCompensationType
  // Shape validated server-side in TM-2 (ported comp-term validator):
  //   commission { rate_pct } | rev_share { rate_pct, cap_usd? }
  //   flat { amount_usd, period } | hybrid { base_usd, rate_pct }
  compensation_terms Json
  expectations       String?
  status             JobListingStatus      @default(draft)
  published_at       DateTime?
  closed_at          DateTime?
  idempotency_key    String?               @unique
  created_at         DateTime              @default(now())
  updated_at         DateTime              @updatedAt

  @@index([status, created_at, id])
  @@index([hirer_id, status])
  @@index([specialty, status])
}

// ─── Applicant ──────────────────────────────────────────────────────────────
//
// Lightweight pre-coach profile (PII) created at Apply, before the job-hunter
// becomes a sub-coach. `user_id` is the pre-coach User account (scalar FK,
// unique — one profile per account). RLS: applicant reads/writes own;
// head-coach SELECT is granted only via the reused TeamSubCoachAssignment
// predicate after a flip. anon → zero rows.
model Applicant {
  id                 String   @id @default(uuid())
  user_id            String   @unique
  email              String
  first_name         String
  last_name          String
  headline           String?
  bio                String?
  specialties        String[]
  certifications     String[]
  years_experience   Int?
  sample_program_url String?
  created_at         DateTime @default(now())
  updated_at         DateTime @updatedAt

  @@index([email])
}

// ─── Application ──────────────────────────────────────────────────────────────
//
// A listing-scoped application (PII). `applicant_id` is the owning Applicant;
// `applicant_user_id` mirrors the pre-coach User for direct owner-scope RLS
// without a join. `fit_score` is the two-way desired-vs-offered indicator
// computed at Apply (TM-5). RLS: applicant reads/writes own; hirer of the
// listing reads applications to their listing.
model Application {
  id                String            @id @default(uuid())
  listing_id        String
  applicant_id      String
  applicant_user_id String
  // Denormalized owning hirer of the listing — lets the hirer-read RLS
  // policy scope by a single column instead of a JobListing sub-select.
  hirer_id          String
  cover_note        String?
  fit_score         Int?
  status            ApplicationStatus @default(submitted)
  idempotency_key   String?           @unique
  created_at        DateTime          @default(now())
  updated_at        DateTime          @updatedAt

  offers CoachOffer[] @relation("CoachOfferApplication")

  // Semantic single-application guard: one Application per (applicant, listing).
  // The idempotency ledger dedups same-key retries, but two DISTINCT
  // client-supplied keys for the same (account, listing) would otherwise create
  // duplicate rows — this composite unique is the DB backstop. A P2002 on it is
  // routed into the idempotent recoverConfirmation path in apply.service.
  @@unique([applicant_user_id, listing_id])
  @@index([listing_id, status, created_at, id])
  @@index([applicant_user_id, created_at, id])
  @@index([hirer_id, status])
}

// ─── CoachOffer ───────────────────────────────────────────────────────────────
//
// A head-coach extends an offer against an Application (financial). One
// application may receive multiple offers from different head-coaches; only
// one may be `accepted` (partial unique index). `head_coach_id` /
// `applicant_user_id` are scalar User FKs at the SQL layer.
model CoachOffer {
  id                 String                @id @default(uuid())
  head_coach_id      String
  application_id     String
  application        Application           @relation("CoachOfferApplication", fields: [application_id], references: [id], onDelete: Cascade)
  applicant_user_id  String
  compensation_type  CoachCompensationType
  compensation_terms Json
  client_capacity    Int
  onboarding_message String?
  status             CoachOfferStatus      @default(pending)
  accepted_at        DateTime?
  idempotency_key    String?               @unique
  created_at         DateTime              @default(now())
  updated_at         DateTime              @updatedAt

  @@index([head_coach_id, status])
  @@index([application_id, status])
}

// ─── MarketplaceMutationIdempotency ─────────────────────────────────────────────
//
// Per-route idempotency ledger for talent-marketplace mutations (ported from
// 714a69af). Composite uniqueness `(user_id, route_key, idempotency_key)`:
// the same UUID may appear under two routes/users — only the same user
// retrying the same mutation hits the cache. `response` is nullable (NULL
// while a claim is `in_progress`; populated on `completed`). RLS: RESTRICTIVE
// deny-all to anon + authenticated — accessed only via service_role.
model MarketplaceMutationIdempotency {
  id              String    @id @default(uuid())
  user_id         String
  route_key       String
  idempotency_key String
  response        Json?
  status          String    @default("completed")
  claim_nonce     String?
  created_at      DateTime  @default(now())
  completed_at    DateTime?

  @@unique([user_id, route_key, idempotency_key])
  @@index([user_id, route_key])
}

// ─── MarketplaceConnectEvent ────────────────────────────────────────────────────
//
// TM-14 — event-driven Stripe Connect `account.updated` ledger for the talent
// marketplace. One row per processed Stripe event id; the `stripe_event_id`
// primary key is the idempotency anchor — a redelivered event loses the unique
// insert race and is processed exactly once (mirrors StripeProcessedEvent).
//
// `onboarding_completed` is the EVENT-DRIVEN completion state derived from the
// account payload via the TM-10 adapter mapping (charges_enabled &&
// payouts_enabled). It replaces polling as the primary onboarding-completed
// signal (fixes P1-7); the legacy ConnectService.syncFromStripe poll stays as
// a fallback only.
//
// RLS: RESTRICTIVE deny-all to anon + authenticated — written/read only via
// service_role (the webhook runs server-side). Mirrors
// MarketplaceMutationIdempotency. See 20261220000030 migration.
model MarketplaceConnectEvent {
  stripe_event_id      String   @id
  type                 String
  stripe_account_id    String
  coach_user_id        String?
  onboarding_completed Boolean  @default(false)
  processed_at         DateTime @default(now())

  @@index([stripe_account_id])
  @@index([coach_user_id])
}

// ─── MarketplaceAbuseSignal ─────────────────────────────────────────────────────
//
// TM-6 — PII-governed heuristic + abuse-log store for the in-house anti-bot
// gate on the apply / account-create surface. One row per gate evaluation.
// All correlatable identifiers are sha256-hashed by the provider BEFORE the
// row is written — this table never holds a raw email / IP / device
// fingerprint, only fixed-width hashes. `reason` is NULL for an allow and a
// stable code (rate_exceeded | velocity_anomaly | duplicate_device |
// duplicate_identity) when the gate challenged/denied.
//
// The duplicate-device / duplicate-identity heuristics read this store:
// distinct identity_hash per device_hash (sock-puppets) and distinct ip_hash
// per identity_hash (rotation) inside the retention window.
//
// RLS: RESTRICTIVE deny-all to anon + authenticated — accessed only via
// service_role (the gate runs server-side). Mirrors
// MarketplaceMutationIdempotency. See 20261220000020 migration.
model MarketplaceAbuseSignal {
  id            String   @id @default(uuid())
  surface       String
  ip_hash       String
  identity_hash String
  device_hash   String
  reason        String?
  created_at    DateTime @default(now())

  @@index([device_hash, created_at])
  @@index([identity_hash, created_at])
  @@index([surface, created_at])
}

// ============================================================
// EXTENSION PAIRING (v0.3 — operator ruling 2026-07-06)
// ============================================================

// Short-lived pairing codes that bridge the TGP mobile app (where coach
// identity lives) and the desktop Chrome importer extension. The mobile app
// mints a 6-digit code bound to the coach + chosen source platform; the
// extension redeems it once for a token bound to that coach. See
// docs/DESIGN.md v0.3 §2/§4. Single-use is enforced by a conditional update on
// used_at; expiry by expires_at. RLS: RESTRICTIVE deny-all to anon +
// authenticated — the rows are only ever touched via the service role.
model ExtensionPairCode {
  id              String    @id @default(uuid())
  code            String    @unique
  coach_id        String
  coach           User      @relation("ExtensionPairCodeCoach", fields: [coach_id], references: [id], onDelete: Cascade)
  chosen_platform String
  expires_at      DateTime
  used_at         DateTime?
  // Per-code brute-force lockout counter. Charged once per redeem that finds
  // the row but fails to claim it; at the service lockout ceiling the code is
  // hard-invalidated (410 locked). DB-backed so lockout survives across IPs.
  failed_attempts Int       @default(0)
  created_at      DateTime  @default(now())

  @@index([coach_id])
  @@index([expires_at])
  @@index([used_at])
}

// ─── ScoutProgressSnapshot ──────────────────────────────────────────────────────
//
// IMPORTER-E — cross-device progress mirroring for the tgp-importer Chrome
// extension (DESIGN.md v0.3 §10). The extension's background worker POSTs its
// status_snapshot to /api/scout/progress on every batch commit so the TGP
// mobile app can mirror crawl progress on its in-app progress screen.
//
// One row per (coach_id, intent_id, device_id): the endpoint UPSERTS the latest
// snapshot (only the newest matters — this is not an append log), so the hot
// path is a single upsert flushed from an in-process cache rather than a write
// per commit. device_id is in the key so a coach mirroring one import from two
// physical devices at once (laptop + phone) keeps two independent rows.
//
// RLS: RESTRICTIVE deny-all to anon + authenticated; service_role bypass only.
// The endpoint runs server-side under the extension bearer token and writes as
// service_role. Mirrors MarketplaceConnectEvent (see 20261220000030 migration).
model ScoutProgressSnapshot {
  id         String   @id @default(uuid())
  coach_id   String
  intent_id  String
  device_id  String
  snapshot   Json
  last_error String?
  updated_at DateTime @default(now()) @updatedAt

  @@unique([coach_id, intent_id, device_id])
  @@index([coach_id])
}

// ─── ScoutImportCompletion ──────────────────────────────────────────────────────
//
// IMPORTER-E — terminal completion ledger for an extension import
// (DESIGN.md v0.3 §2 step 11). The extension POSTs /api/scout/ingest/complete
// once the crawl settles; the row is the idempotency anchor.
//
// The @@unique([coach_id, intent_id]) makes completion exactly-once: a retry
// after a network flake loses the unique-insert race and is treated as a no-op,
// so the coach is never double-notified. When Lane 3's scout ingest table
// (IMPORTER-B) lands, the settle step can additionally flip that import row's
// state; this ledger is the independent source of truth until then.
//
// RLS: RESTRICTIVE deny-all to anon + authenticated; service_role bypass only.
model ScoutImportCompletion {
  id              String   @id @default(uuid())
  coach_id        String
  intent_id       String
  terminal_status String
  final_counts    Json?
  error_summary   String?
  completed_at    DateTime @default(now())

  @@unique([coach_id, intent_id])
  @@index([coach_id])
}

// ─── ScoutImport ────────────────────────────────────────────────────────────────
//
// IMPORTER-E — parent lifecycle state for an extension import (R-STATE-1).
// The completion ledger (ScoutImportCompletion) records THAT a settle happened;
// this table owns the import's current lifecycle STATE so the ingest side is not
// stuck reading `in_progress` forever. /api/scout/ingest/complete flips `state`
// to the reported terminal_status atomically, in the same $transaction as the
// ledger insert, so the two can never disagree.
//
// `state` carries the lifecycle value: it starts at `in_progress` and is set to
// the terminal_status (`success` | `partial` | `failed`) on settle.
// `terminal_status` mirrors that terminal value for ledger parity and stays
// null until the import settles. A second /complete for the same
// (coach_id, intent_id) hits the ledger unique constraint, the transaction
// rolls back, and the state is never re-flipped (idempotent settle).
//
// RLS: RESTRICTIVE deny-all to anon + authenticated; service_role bypass only,
// the same posture as the other scout tables.
model ScoutImport {
  id              String    @id @default(uuid())
  coach_id        String
  intent_id       String
  state           String    @default("in_progress")
  terminal_status String?
  started_at      DateTime  @default(now())
  completed_at    DateTime?

  @@unique([coach_id, intent_id])
  @@index([coach_id])
}

// ─── ScoutIngestEntity ──────────────────────────────────────────────────────────
//
// IMPORTER-B — receiver store for the tgp-importer extension's autonomous crawl
// envelope (POST /api/scout/ingest). One row per ingested entity. The envelope
// shape is the R80-locked contract in tgp-importer-extension extractors/_interface.js
// (makeEntity is the source of truth over the file's header comment):
//   { intent_id, entity_type, entities:[{ sourceId, sourcePlatform, payload, capturedAt }] }
// Provenance (sourceId/sourcePlatform/capturedAt) is top-level camelCase on each
// entity; only intent_id/entity_type on the outer envelope stay snake_case.
//
// coach_id comes from the extension bearer-token identity (never a body field);
// the (coach_id, intent_id, source_id) unique key makes the endpoint idempotent
// so the extension can safely replay a batch during retry/recovery without
// duplicating rows.
//
// RLS: RESTRICTIVE deny-all to anon + authenticated — written/read only via
// service_role (the ingest endpoint runs server-side). Mirrors
// MarketplaceMutationIdempotency. See the companion migration.
model ScoutIngestEntity {
  id              String    @id @default(uuid())
  coach_id        String
  intent_id       String
  entity_type     String
  source_id       String
  source_platform String
  captured_at     DateTime?
  payload         Json
  created_at      DateTime  @default(now())

  @@unique([coach_id, intent_id, source_id])
  @@index([coach_id, entity_type])
}

// ============================================================
// IMPORTER-F — scout reconstruction (D2: invite-pending roster)
// ============================================================

// D2 (DECIDED, Op 59): the canonical target for an imported client is an
// invite-pending, NON-LOGIN, tenant-owned roster record — NOT an auth User or
// any credential. A Person is linked to an AuthPrincipal only later, via an
// explicit credential-verified claim (out of scope here). Email is unverified
// imported data and is deliberately NOT stored as a column and NEVER used as a
// canonical id or linking key. Identity is the opaque server-issued `id`
// (person_id); dedup/idempotency is the tenant-scoped external_ref
// (coach_id, source_platform, source_person_id).
enum PersonState {
  InvitePending
  Invited
  Claimed
  Suspended
  Deleted
}

model Person {
  id               String      @id @default(uuid())
  coach_id         String
  source_platform  String
  source_person_id String
  display_name     String?
  state            PersonState @default(InvitePending)
  created_at       DateTime    @default(now())
  updated_at       DateTime    @default(now()) @updatedAt

  // external_ref idempotency key — a source entity maps to exactly one roster
  // Person per tenant, so reconstruction replays are no-ops.
  @@unique([coach_id, source_platform, source_person_id])
  @@index([coach_id])
}

// Per-entity reconciliation ledger: honest accounting for one reconstruction
// pass. staged = reconstructed + skipped + failed; non-reconstructed outcomes
// carry a reason. Keyed for idempotent replay.
model ScoutReconstructionLedger {
  id          String   @id @default(uuid())
  coach_id    String
  intent_id   String
  entity_type String
  source_id   String
  status      String
  target_id   String?
  reason      String?
  created_at  DateTime @default(now())

  @@unique([coach_id, intent_id, entity_type, source_id])
  @@index([coach_id, intent_id])
}

// ============================================================
// IMPORTER-H — multi-family reconstruction (canonical non-person entities)
// ============================================================
//
// D2, site-agnostic. IMPORTER-F reconstructs the `clients` family into `Person`
// (a renderable roster identity). Families that are NOT people — `workouts`,
// `client_history` — reconstruct into ONE generic, tenant-owned canonical table
// instead of a per-family clone. This is the "one parameterized mechanism": the
// reconstruction engine is keyed on entity_type via a family registry, and every
// non-person family shares this table.
//
// Identity/idempotency is the tenant-scoped external_ref
// (coach_id, source_platform, entity_type, source_id) — the source platform's
// own opaque record id, never email and never a billing key. `client_source_id`
// is a SOFT provenance link to the owning Person's external_ref
// (coach_id, source_platform, client_source_id) — no FK, mirroring the no-FK
// posture of the other scout tables. `label` is a best-effort, PII-minimal
// display string (a title/name), never email, never any billing/price field.
//
// RLS: same fail-closed posture as Person / ScoutReconstructionLedger —
// service_role PERMISSIVE bypass, anon + authenticated RESTRICTIVE deny-all.
model ScoutReconstructedEntity {
  id               String   @id @default(uuid())
  coach_id         String
  source_platform  String
  entity_type      String
  source_id        String
  client_source_id String?
  label            String?
  created_at       DateTime @default(now())
  updated_at       DateTime @default(now()) @updatedAt

  @@unique([coach_id, source_platform, entity_type, source_id])
  @@index([coach_id, entity_type])
}

// The Growth Project — Prisma Schema
// PostgreSQL with Supabase Auth integration

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider  = "postgresql"
  // DATABASE_URL  → Supabase pgbouncer pooler (port 6543, ?pgbouncer=true)
  //                 Used by the runtime app for all query traffic.
  // DIRECT_URL    → Supabase direct connection (port 5432, no pgbouncer param)
  //                 Used only by `prisma migrate deploy` in the Fly release_command.
  //                 Migrations require a real Postgres session, not a pooled one.
  //                 Set this in Fly with:
  //                   fly secrets set DIRECT_URL="postgres://postgres.<ref>:<pw>@aws-0-us-west-1.pooler.supabase.com:5432/postgres"
  url       = env("DATABASE_URL")
  directUrl = env("DIRECT_URL")
}

// ============================================================
// ENUMS
// ============================================================

// Phase 1A platform pivot: add the `owner` tier above `coach` so the
// platform can be operated as Healthie-style OWNER -> COACH -> CLIENT
// without breaking existing rows. Existing rows stay valid (`coach`,
// `student`); the new `owner` value is opt-in and only set by the
// bootstrap-owners script or the OWNER promote endpoint.
enum Role {
  coach
  student
  owner
  sub_coach
}

// Phase 1A: subscription state for a coach's $300/mo seat. Stored as
// strings on CoachProfile so the column reads naturally in raw SQL and
// admin tooling without a Prisma-only enum mapping.
enum SubscriptionStatus {
  active
  trialing
  past_due
  canceled
  paused
}

enum Sex {
  male
  female
  prefer_not_to_say
}

enum ActivityLevel {
  sedentary
  light
  moderate
  active
  very_active
}

enum GoalType {
  fat_loss
  muscle_gain
  maintenance
  performance
}

enum WorkoutExperience {
  beginner
  intermediate
  advanced
}

enum FoodCategory {
  generic
  packaged
  fast_food
  restaurant
  recipe_ingredient
}

// Canonical basis for the macro columns on FoodItem.
//   PER_100G    — calories/protein/carbs/fat are expressed per 100g of the food.
//                 This is the basis USDA FDC and OpenFoodFacts return; the
//                 backend stores them verbatim. Mobile multiplies by
//                 (grams_consumed / 100) at log time.
//   PER_SERVING — macros are expressed per one `serving_size_grams` unit.
//                 Reserved for legacy / hand-curated entries where per-100g
//                 data is unavailable. New rows default to PER_100G.
// See README "Food logger — canonical nutrient basis" for the contract.
enum NutrientBasis {
  PER_100G
  PER_SERVING
}

enum MealType {
  breakfast
  lunch
  dinner
  snack
}

enum Intensity {
  light
  moderate
  hard
  max
}

enum MuscleGroup {
  chest
  back
  legs
  shoulders
  arms
  core
  cardio
  full_body
}

enum CheckInType {
  morning
  evening
}

// CoachPracticeType — Stage-3 cross-pillar federation gate.
//
// What kind of practice the coach runs across the TGP product family
// (Body / Wealth). The cross-pillar surface in `/api/coach/cross-pillar/*`
// is gated on `both`; coaches with `fitness_only` or `finance_only` see
// their existing single-product coach console unchanged. `null` on the
// User row means the coach has not yet selected — the cross-pillar
// surface returns `403 PRACTICE_NOT_SELECTED` and the mobile app routes
// them through the practice-selection flow.
enum CoachPracticeType {
  fitness_only
  finance_only
  both
}

// Hybrid pricing tier for coaches (§3 spec v1.0.0).
// 'enterprise' is reserved for future use — no logic enforces it today.
// The column exists so future enterprise features do not require a schema migration.
enum CoachTier {
  free
  pro
  enterprise
}

// ============================================================
// MODELS
// ============================================================

model User {
  id                        String             @id @default(uuid())
  supabase_id               String             @unique
  email                     String             @unique
  name                      String
  phone                     String?
  role                      Role               @default(student)
  // coach_id now a proper self-relation FK instead of an orphan string column.
  // Preserves prior behavior — still nullable, still points at another User.id.
  coach_id                  String?
  coach                     User?              @relation("CoachToStudents", fields: [coach_id], references: [id])
  students                  User[]             @relation("CoachToStudents")
  // Stage-3 cross-pillar federation. Only meaningful when `role = coach`
  // or `owner`; ignored for students. Null = not yet selected.
  coach_practice_type       CoachPracticeType?
  created_at                DateTime           @default(now())
  archived_at               DateTime?
  // GDPR delete-account flow. Two-phase: deletion_scheduled_at marks the
  // grace-period start (account locked but recoverable); deleted_at marks
  // the irreversible PII scrub. Existing rows stay valid (both null).
  deletion_scheduled_at     DateTime?
  deleted_at                DateTime?
  // Phase 10 — explicit user/admin-initiated right-to-erasure flow.
  // deletion_token_hash/expires_at drive the confirmation link email;
  // deletion_requested_at/confirmed_at drive the state machine.
  // Columns added by migration 20260507100000_add_gdpr_deletion_flow.
  deletion_token_hash       String?
  deletion_token_expires_at DateTime?
  deletion_requested_at     DateTime?
  deletion_confirmed_at     DateTime?
  // Push notifications — Expo push token registered from the mobile app.
  // Null means the user has not granted permission or has signed out.
  expo_push_token           String?
  // Signup attribution ref (e.g. "importer-extension"). Null for users who
  // signed up before this column or via a surface that carries no ref.
  signup_ref                String?

  profile                        UserProfile?
  logged_entries                 LoggedFoodEntry[]
  workouts                       WorkoutSession[]
  fasting_windows                FastingWindow[]
  weight_logs                    WeightLog[]
  notification_prefs             NotificationPreferences?
  preferences                    UserPreferences?
  habits                         Habit[]
  lesson_completions             LessonCompletion[]
  check_ins                      CheckIn[]
  water_logs                     WaterLog[]
  created_routines               WorkoutRoutine[]         @relation("RoutineCreator")
  coached_lessons                Lesson[]                 @relation("LessonCoach")
  invite_codes                   InviteCode[]             @relation("CoachInviteCodes")
  coach_messages_as_coach        CoachMessage[]           @relation("CoachMessagesAsCoach")
  coach_messages_as_client       CoachMessage[]           @relation("CoachMessagesAsClient")
  coach_messages_sent            CoachMessage[]           @relation("CoachMessagesSender")
  // ED.6 (Roman coach-is-watching) — per-thread coach-review markers this user
  // participates in, as coach and as client.
  conversation_reviews_as_coach  ConversationReview[]     @relation("ConversationReviewCoach")
  conversation_reviews_as_client ConversationReview[]     @relation("ConversationReviewClient")
  // Apple 1.2 — safety: reports filed by this user, blocks they have set,
  // and inbound blocks against them. The reviewer relation is owner-staff only.
  reports_filed                  MessageReport[]          @relation("MessageReportReporter")
  reports_reviewed               MessageReport[]          @relation("MessageReportReviewer")
  blocks_set                     UserBlock[]              @relation("UserBlockBlocker")
